/-- One of the two force-delete actions, which `s3:*` does not grant. -/
def IsForceDelete (a : acts.Action) : Prop :=
  a.family = .S3 ∧ (nats a.name.val = lit "s3:ForceDeleteBucket" ∨ nats a.name.val = lit "s3:ForceDeleteObject")

kernel.code:
/// `ActionSet::statement_covers`.
pub fn statement_covers(actions: &[Action], not_actions: &[Action], a: &Action, deny: bool) -> bool {
    if set_is_match_for_effect(not_actions, a, true) {
        return false;
    }
    if actions.len() == 0 {
        return deny || !action_requires_explicit_grant(a);
    }
    set_is_match_for_effect(actions, a, deny)
}

/// `action_requires_explicit_grant`.
pub fn action_requires_explicit_grant(a: &Action) -> bool {
    is_s3(a, b"s3:ForceDeleteBucket") || is_s3(a, b"s3:ForceDeleteObject")
}

/// `ActionSet::is_match_for_effect`.
pub fn set_is_match_for_effect(set: &[Action], a: &Action, deny: bool) -> bool {
    let mut i = 0;
    while i < set.len() {
        if action_is_match_for_effect(&set[i], a, deny) {
            return true;
        }
        if is_s3(&set[i], b"s3:GetObjectVersion") && is_s3(a, b"s3:GetObject") {
            return true;
        }
        i += 1;
    }
    false
}

fn is_s3(a: &Action, name: &[u8]) -> bool {
    a.family == Family::S3 && bytes::eq(&a.name, name)
}

upstream.code:
/// Whether a statement with this `Action` list and `not_actions` as its
/// `NotAction` list covers `action`.
///
/// `NotAction` always uses plain wildcard matching, so `NotAction: "s3:*"`
/// still excludes force-delete. An Allow grants force-delete only when its
/// `Action` list names it: an Allow built from `NotAction` alone never does.
pub fn statement_covers(&self, not_actions: &ActionSet, action: &Action, deny: bool) -> bool {
    if not_actions.is_match_for_effect(action, true) {
        return false;
    }
    if self.is_empty() {
        return deny || !action_requires_explicit_grant(action);
    }
    self.is_match_for_effect(action, deny)
}

fn action_requires_explicit_grant(action: &Action) -> bool {
    matches!(
        action,
        Action::S3Action(S3Action::ForceDeleteBucketAction | S3Action::ForceDeleteObjectAction)
    )
}

